 51 | /**
 52 |  * The shared give_hint tool. It is the only hint sink: the server-side guard runs
 53 |  * here before a hint is recorded, and a rejected hint becomes a tool error so the
 54 |  * model rephrases instead of the hint reaching the student.
 55 |  */
 56 | const giveHintTool = createTool({
 57 |   name: "give_hint",
 58 |   description: GIVE_HINT_DESCRIPTION,
 59 |   inputSchema: z.object({
 60 |     level: z.number().int().min(1).max(3),
 61 |     tag: z.string().optional(),
 62 |     text: z.string(),
 63 |   }),
 64 |   async execute(input, context) {
 65 |     const session = context.sessionId ? getSession(context.sessionId) : undefined;
 66 |     const wanted = session?.currentHintLevel ?? input.level;
 67 | 
 68 |     if (session && input.level !== wanted) {
 69 |       emitEvent(session, "hint_rejected", {
 70 |         level: input.level,
 71 |         wantedLevel: wanted,
 72 |         reason: "wrong level",
 73 |       });
 74 |       throw new Error(
 75 |         `You were asked for a level ${wanted} hint, but called give_hint with level ${input.level}. ` +
 76 |           `Call give_hint again with level ${wanted}.`,
 77 |       );
 78 |     }
 79 | 
 80 |     if (session && session.hints.some((h) => h.level === input.level)) {
 81 |       // This level was already delivered; tell the model to stop without erroring,
 82 |       // so it finishes its turn instead of retrying forever.
 83 |       return {
 84 |         shown: false,
 85 |         alreadyDelivered: true,
 86 |         message: `The level ${input.level} hint was already delivered. Do not call give_hint again; finish your turn.`,
 87 |       };
 88 |     }
 89 | 
 90 |     const guard = checkHint(input.text);
 91 |     if (!guard.ok) {
 92 |       if (session) {
 93 |         // Never surface the rejected text — only a fixed reason category.
 94 |         emitEvent(session, "hint_rejected", {
 95 |           level: input.level,
 96 |           reason: categorizeHintReason(guard.reason),
 97 |         });
 98 |       }
 99 |       throw new Error(
100 |         `HintLab rejected this hint: ${guard.reason}. Rephrase the hint in plain prose with no code, ` +
101 |           `then call give_hint again.`,
102 |       );
103 |     }
104 | 
105 |     const hint = {
106 |       level: input.level as 1 | 2 | 3,
107 |       tag: input.tag,
108 |       text: input.text,
109 |       at: new Date().toISOString(),
110 |     };
111 |     if (session) {
112 |       recordHint(session, hint);
113 |     }
114 |     return { shown: true, level: input.level };
115 |   },
116 | });
