196 | /** Map the raw SDK events to HintLab SSE events, routed by session id. */
197 | function handleCoreEvent(e: {
198 |   type: string;
199 |   payload?: { sessionId?: string; event?: Record<string, unknown>; [k: string]: unknown };
200 | }): void {
201 |   const sessionId = e.payload?.sessionId;
202 |   if (!sessionId) return;
203 |   const session = getSession(sessionId);
204 |   if (!session) return;
205 | 
206 |   if (e.type === "agent_event") {
207 |     const ev = e.payload?.event as Record<string, unknown> | undefined;
208 |     if (!ev) return;
209 |     switch (ev.type) {
210 |       case "content_start":
211 |         // Only tool starts are forwarded (and then filtered to the allow-list).
212 |         // Model text and reasoning are dropped here and never emitted.
213 |         if (ev.contentType === "tool") {
214 |           emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, input: ev.input });
215 |         }
216 |         break;
217 |       case "content_end":
218 |         if (ev.contentType === "tool") {
219 |           emitEvent(session, "tool_result", {
220 |             toolName: ev.toolName,
221 |             toolCallId: ev.toolCallId,
222 |             output: ev.output,
223 |             error: ev.error,
224 |             durationMs: ev.durationMs,
225 |           });
226 |         }
227 |         break;
228 |       case "done":
229 |         emitEvent(session, "done", { reason: ev.reason });
230 |         break;
231 |       case "error":
232 |         handleAgentError(session, ev);
233 |         break;
234 |       default:
235 |         break;
236 |     }
237 |     return;
238 |   }
239 | 
240 |   if (e.type === "status") {
241 |     emitEvent(session, "status", { status: e.payload?.status });
242 |   } else if (e.type === "ended") {
243 |     emitEvent(session, "done", { reason: e.payload?.reason });
244 |   } else if (e.type === "hook") {
245 |     const payload = e.payload as Record<string, unknown>;
246 |     emitEvent(session, "status", { hook: payload.hookEventName, toolName: payload.toolName });
247 |   }
248 | }
