251 | /** Lazily create the one shared ClineCore instance and subscribe once. */
252 | async function getCline(): Promise<ClineCore> {
253 |   if (!clineCorePromise) {
254 |     clineCorePromise = (async () => {
255 |       const cline = await ClineCore.create({ clientName: "hintlab", backendMode: "local" });
256 |       cline.subscribe((e: unknown) => handleCoreEvent(e as Parameters<typeof handleCoreEvent>[0]));
257 |       return cline;
258 |     })();
259 |   }
260 |   return clineCorePromise;
