326 | /**
327 |  * Emit the right error event for a session and end it in the `error` state.
328 |  * Auth failures are collapsed into one short, secret-free message (logged
329 |  * once per session with the session id); everything else keeps its existing
330 |  * friendly handling in the event filter.
331 |  */
332 | function handleAgentError(session: Session, err: unknown): void {
333 |   if (detectAuthFailure(err)) {
334 |     if (!session.authFailureHandled) {
335 |       session.authFailureHandled = true;
336 |       // Exactly one line per failed session, no stack traces or secrets.
337 |       console.log(`[session ${session.id}] ${AUTH_FAILURE_MESSAGE}`);
338 |       emitEvent(session, "error", { message: AUTH_FAILURE_MESSAGE, code: AUTH_FAILURE_CODE });
339 |     }
340 |     setStatus(session, "error");
341 |     return;
342 |   }
343 | 
344 |   emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
345 |   setStatus(session, "error");
346 | }
