348 | /** Run the first (level-1) agent turn in the background for a session. */
349 | export async function startSession(sessionId: string): Promise<void> {
350 |   const session = getSession(sessionId);
351 |   if (!session) return;
352 | 
353 |   const mainFile = session.language === "python" ? "main.py" : "main.c";
354 |   const mainPath = path.resolve(session.workdir, mainFile);
355 |   const testsPath = path.resolve(session.workdir, "tests.json");
356 | 
357 |   const cline = await getCline();
358 |   session.busy = true;
359 |   setStatus(session, "running");
360 | 
361 |   try {
362 |     const startPromise = cline.start({
363 |       interactive: true,
364 |       prompt: buildFirstPrompt(session, mainPath, testsPath),
365 |       config: {
366 |         sessionId: session.id,
367 |         providerId: HINTLAB_PROVIDER_ID,
368 |         modelId: HINTLAB_MODEL_ID,
369 |         temperature: 0,
370 |         systemPrompt: SYSTEM_PROMPT,
371 |         // session.workdir is the runner's temp sandbox dir, kept alive for the
372 |         // agent via runAssignment(..., { cleanup: false }) in app.ts. It is the
373 |         // agent's whole sandbox and is removed by the session cleanup loop when
374 |         // the session ends/TTL expires (see sessions.ts deleteSession).
375 |         cwd: session.workdir,
376 |         workspaceRoot: session.workdir,
377 |         enableTools: true,
378 |         enableSpawnAgent: false,
379 |         enableAgentTeams: false,
380 |         extraTools: [giveHintTool as unknown as AgentTool, runTestsTool as unknown as AgentTool],
381 |       },
382 |       toolPolicies: toolPolicies(),
383 |       capabilities: capabilities(),
384 |     });
385 |     startPromise.catch(() => undefined); // swallow late settle after a timeout
386 | 
387 |     const result = await withTimeout(startPromise, AGENT_TURN_TIMEOUT_MS, "Tutor timed out, try again");
388 | 
389 |     session.agentSessionId = result.sessionId;
390 |     registerAgentSession(result.sessionId, session.id);
391 |     const finishReason = (result.result as { finishReason?: string } | undefined)?.finishReason;
392 |     emitEvent(session, "status", { message: "initial agent turn finished", finishReason });
393 |   } catch (err) {
394 |     handleAgentError(session, err);
395 |   } finally {
396 |     session.busy = false;
397 |     if (session.status !== "error") {
398 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
399 |     }
400 |   }
401 | }
