403 | /** Ask the agent for the next hint level (2, then 3). Returns after the turn completes. */
404 | export async function nextHint(sessionId: string): Promise<{ level: number; status: string; message?: string }> {
405 |   const session = getSession(sessionId);
406 |   if (!session) throw Object.assign(new Error("unknown session"), { status: 404 });
407 |   if (session.busy) throw Object.assign(new Error("agent is still busy"), { status: 409 });
408 |   if (session.hints.length >= 3) {
409 |     return { level: 3, status: "complete", message: "All three hint levels have already been delivered." };
410 |   }
411 | 
412 |   const nextLevel = Math.min(session.hints.length + 1, 3);
413 |   session.currentHintLevel = nextLevel;
414 |   session.busy = true;
415 |   setStatus(session, "running");
416 | 
417 |   const cline = await getCline();
418 |   try {
419 |     const sendPromise = cline.send({
420 |       sessionId: session.agentSessionId ?? session.id,
421 |       prompt: buildNextPrompt(session, nextLevel),
422 |     });
423 |     sendPromise.catch(() => undefined); // swallow late settle after a timeout
424 |     const result = await withTimeout(sendPromise, AGENT_TURN_TIMEOUT_MS, "Tutor timed out, try again");
425 |     const finishReason = (result as { finishReason?: string } | undefined)?.finishReason;
426 |     emitEvent(session, "status", { message: `level ${nextLevel} agent turn finished`, finishReason });
427 |   } catch (err) {
428 |     handleAgentError(session, err);
