103 |   app.get("/api/session/:id/stream", (req: Request, res: Response) => {
104 |     const session = getSession(String(req.params.id));
105 |     if (!session) {
106 |       res.status(404).json({ error: "unknown session" });
107 |       return;
108 |     }
109 | 
110 |     openSse(res);
111 |     res.write(": connected\n\n");
112 |     addClient(session, res); // replays buffered events + registers for live events
113 | 
114 |     const heartbeat = setInterval(() => {
