114 | async function waitUntil(fn: () => boolean, what: string, timeoutMs: number): Promise<void> {
115 |   const deadline = Date.now() + timeoutMs;
116 |   while (Date.now() < deadline) {
117 |     if (fn()) return;
118 |     await new Promise((r) => setTimeout(r, 100));
119 |   }
120 |   throw new Error(`timeout waiting for ${what}`);
121 | }
